                                print(line[:200])
            except Exception as e:
                pass

# Also search for numbers that could be thresholds
print('\n=== Search for clinical thresholds ===')
for root, dirs, files in os.walk('.'):
    for f in files:
        path = os.path.join(root, f)
        if f.endswith('.md'):
